<template><div><PageHeader eyebrow="Usage Comparison" title="企业用量对比" description="选择 2–8 家企业，对比指定周期内的聚合用量。"><button class="layui-btn monitor-secondary" :disabled="!comparison.enterprises?.length" @click="exportCsv">导出数据</button></PageHeader><section class="panel filter-panel"><div class="compare-filter"><div class="field"><label>选择企业（{{selectedIds.length}}/8）</label><div class="company-options"><label v-for="item in options" :key="item.id"><input v-model="selectedIds" type="checkbox" :value="item.id" :disabled="!selectedIds.includes(item.id)&&selectedIds.length>=8"> {{item.name}}</label></div><p v-if="selectionError" class="error-text">{{selectionError}}</p></div><div class="field"><label>统计周期</label><select v-model.number="days" class="layui-select"><option :value="7">近 7 天</option><option :value="14">近 14 天</option><option :value="30">近 30 天</option></select></div><button class="layui-btn monitor-primary" :disabled="loading" @click="compare">{{loading?'加载中':'开始对比'}}</button></div></section><template v-if="comparison.enterprises?.length"><section class="comparison-chart-grid"><article class="panel"><header class="panel-header"><div><h2>系统调用量趋势</h2><p>图例可点击隐藏企业</p></div><span class="tag success">{{comparison.enterprises.length}} 家企业</span></header><div class="panel-body"><LineChart :labels="labels" :series="series" /></div></article><article class="panel"><header class="panel-header"><div><h2>企业用量占比</h2><p>所选周期内系统调用总量占比</p></div></header><div class="panel-body"><PieChart :data="pieData" /></div></article></section><section class="equal-grid compare-summary"><article v-for="(item,index) in cards" :key="item.enterpriseId" class="panel panel-body"><span class="tag">用量第 {{index+1}}</span><h3>{{item.enterpriseName}}</h3><div class="compare-values"><div><span>累计出单</span><strong>{{format(item.workorders)}}</strong></div><div><span>系统调用</span><strong>{{format(item.requests)}}</strong></div><div><span>OCR 使用</span><strong>{{format(item.ocr)}}</strong></div></div></article></section></template><div v-else class="panel empty-state">请选择至少 2 家企业开始对比。</div></div></template>
<script>import PageHeader from '@/components/PageHeader.vue';import LineChart from '@/components/LineChart.vue';import PieChart from '@/components/PieChart.vue';import { enterpriseApi } from '@/api/monitor';export default{name:'EnterpriseComparePage',components:{PageHeader,LineChart,PieChart},data:()=>({options:[],selectedIds:[1,2,3],days:30,comparison:{enterprises:[]},loading:false,selectionError:''}),computed:{labels(){return this.comparison.dates?.map(d=>d.slice(5))||[];},series(){return this.comparison.enterprises.map(e=>({name:e.enterpriseName,data:e.points.map(p=>p.requestCount),area:false}));},cards(){return this.comparison.enterprises.map(e=>({enterpriseId:e.enterpriseId,enterpriseName:e.enterpriseName,workorders:e.points.reduce((s,p)=>s+p.workorderCount,0),requests:e.points.reduce((s,p)=>s+p.requestCount,0),ocr:e.points.reduce((s,p)=>s+p.ocrCount,0)})).sort((a,b)=>b.requests-a.requests);},pieData(){return this.cards.map(i=>({name:i.enterpriseName.replace(/有限公司$/,''),value:i.requests}));}},mounted(){enterpriseApi.options().then(data=>{this.options=data;this.compare();});},methods:{format:v=>Number(v||0).toLocaleString('zh-CN'),async compare(){if(this.selectedIds.length<2){this.selectionError='请至少选择 2 家企业';return;}this.selectionError='';this.loading=true;try{this.comparison=await enterpriseApi.compare({enterpriseIds:this.selectedIds.join(','),days:this.days});}finally{this.loading=false;}},exportCsv(){const rows=[['企业','累计出单','系统调用','OCR使用'],...this.cards.map(i=>[i.enterpriseName,i.workorders,i.requests,i.ocr])];const blob=new Blob(['\ufeff'+rows.map(r=>r.join(',')).join('\n')],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='企业用量对比.csv';a.click();URL.revokeObjectURL(a.href);}}};</script><style scoped>.compare-filter{display:grid;grid-template-columns:1fr 160px auto;align-items:end;gap:14px}.company-options{display:flex;gap:12px;flex-wrap:wrap;min-height:40px;padding:8px 10px;border:1px solid #cbd5e1;border-radius:6px}.company-options label{white-space:nowrap}.comparison-chart-grid{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(360px,1fr);gap:16px;margin-bottom:16px}.compare-summary{grid-template-columns:repeat(3,1fr)}.compare-summary h3{margin:13px 0}.compare-values{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.compare-values span{display:block;color:var(--muted);font-size:12px}.compare-values strong{display:block;margin-top:5px}@media(max-width:1100px){.comparison-chart-grid{grid-template-columns:1fr}}@media(max-width:900px){.compare-summary,.compare-filter{grid-template-columns:1fr}}</style>
